const e={inkAcceleration:{name:"Ink Acceleration / Ramp",emoji:"⚡",description:"Accelerate ink early (turns 1-2) to deploy powerful threats ahead of schedule. Win condition: overpower opponents with superior card advantage and bigger threats.",coreMechanic:"Use Sapphire/Emerald cards to add extra ink, then deploy expensive finishers early",lorcanaExamples:[{archetype:"Emerald/Sapphire Control",keyCards:["Tipo - Growing Son","Sail the Azurite Sea","Cinderella - Dream Come True","Clarabelle - Light on Her Hooves","Basil - Undercover Detective"],gameplan:"Turn 1-2: Build ink with Tipo/Sail. Turn 3-4: Clarabelle for card draw. Turn 5+: Slam Prince Phillip/board wipes.",strengths:["Card advantage engine","Late game power","Flexible answers"],weaknesses:["Vulnerable early","Dies to fast aggro","Hand disruption hurts"],skillLevel:"Medium-High"}],tips:["Prioritize ink accelerators early - they enable everything","Have a payoff card in mind before accelerating (draw, removal, threat)","Keep cheap blockers to survive initial aggression","Hold disruption for their payoff turn"],crossTCGComparison:{magic:"Green Ramp / Mana Acceleration (Black Lotus, Llanowar Elves, Cultivate)",yugioh:"Blue-Eyes Engine (card draw + fusion for big monsters), Synchron decks (Synchro Summoning)",pokemon:"Malamar (ability-based acceleration), Arcanine (energy acceleration)",comparison:"Uses resource acceleration (ink/mana/energy) to cheat big threats into play faster than normal curve"}},aggro:{name:"Aggro / Fast Attack",emoji:"⚔️",description:"Play cheap creatures and attack relentlessly. Win condition: Deal 20 damage before opponent stabilizes.",coreMechanic:"Flood board with low-cost characters, generate lore pressure",lorcanaExamples:[{archetype:"Amber/Emerald Dogs",keyCards:["Lady - Decisive Dog","Tramp - Enterprising Dog","Tramp - Street-Smart Dog","Bobby Zimuruski - Spray Cheese Kid","Under the Sea"],gameplan:"Turn 1: Play 1-2 cost dogs. Turn 2-3: Continue curve, fuel Tramp. Turn 4-5: Close out game before removal arrives.",strengths:["Extremely fast","Strong card synergies","High skill ceiling"],weaknesses:["Dies to board wipes","Weak to lifegain","Runs out of gas"],skillLevel:"Medium-High"},{archetype:"Amethyst/Emerald Hyper-Aggro",keyCards:["Enigmatic Inkcaster","28 one-cost creatures","Amethyst Chromicon","Show Me More!","They Never Come Back"],gameplan:"Turn 1-5: Play 2 creatures per turn, triggering Enigmatic Inkcaster for free lore. Refill hand with cheap draw. Close ASAP.",strengths:["Ultra-fast","Incredibly cheap","Beats control"],weaknesses:["Loses to Amethyst Steel","Vulnerable to removal","Low late game"],skillLevel:"Low-Medium"}],tips:["Know your race - are you the beatdown? Go for it.","Sequence creatures strategically - don't play into board wipes","Value synergies but don't force bad cards","Mulligan for early threats, not late game bombs","Be careful about overextending into removal"],crossTCGComparison:{magic:"Red Aggro (Goblin Guides, Lightning Bolt) / White Weenie (Isamaru, Serra's Zealots)",yugioh:"Infernoid (burn/aggro), Red-Eyes aggressive builds, Speedroid decks",pokemon:"Miltank/Donphan (early pressure), Pikachu aggro, V-STAR fast builds",comparison:"Outputs maximum early pressure with cheap creatures to win before opponent stabilizes"}},midrange:{name:"Midrange / Balanced",emoji:"⚖️",description:"Balance offense and defense. Win condition: Use superior value and board control to grind out wins.",coreMechanic:"Play efficient creatures at every cost, accumulate value, control board",lorcanaExamples:[{archetype:"Amethyst/Steel",keyCards:["Calhoun - Bold Knight","Captain Hook - Forceful Duelist","Strength of a Raging Fire","Doc - Bold Knight","Giant Cobra - Ghostly Serpent"],gameplan:"Curve 1-2-3-4 efficiently. Use Strength of a Raging Fire to stabilize. Generate card advantage with Doc/Dumbo. Grind to victory.",strengths:["Perfect curve","Card advantage","Crushes aggro"],weaknesses:["Loses to Amethyst Sapphire","No late-game bombs","Can run out of answers"],skillLevel:"Medium"},{archetype:"Amber/Amethyst Lantern",keyCards:["Lantern","The Horseman Strikes!","Mowgli - Man Cub","Eilonwy - Princess of Llyr","World's Greatest Criminal Mind"],gameplan:"Drop Lantern for ramp. Use Amber/Amethyst removal. Deploy Mowgli as catchall answer. Lantern generates consistent value.",strengths:["Flexible","Good removal suite","Unexpected"],weaknesses:["Lantern-dependent","Can stumble","Learning curve"],skillLevel:"Medium-High"}],tips:["Know your removal suite - use it efficiently","Build a curve with creatures and answers interleaved","Value is king - every card should trade for 1.5+ opponent's cards","Play on the cheap side early to answer aggro, shift to threats later","In mulligan: Keep hands with turn 2-3 plays and removal"],crossTCGComparison:{magic:"GX/RG Midrange (Tarmogoyf, Seasoned Pyromancer) / Jund",yugioh:"Swordsoul (balanced creatures + removal), Tearlaments (midrange control)",pokemon:"Lugia VSTAR (balanced approach), Raichu decks, Evolution decks",comparison:"Uses efficiently costed creatures with disruption to control the game state while building threats"}},tempo:{name:"Tempo / Disruption",emoji:"⏰",description:"Control the game with cheap creatures and disruption. Win condition: Keep opponent off-balance while you attack.",coreMechanic:"Use challenges, hand disruption, and tempo creatures to disrupt opponent's gameplan",lorcanaExamples:[{archetype:"Steel/Sapphire Tempo",keyCards:["Steel creatures with Challenge evasion","Sapphire hand disruption","Basil - Undercover Detective","Into the Unknown","Royal Guard - Octopus Soldier"],gameplan:"Play cheap creatures they can't challenge. Use Basil/hand disruption to discard threats. Attack while denying their answers.",strengths:["Disrupts gameplan","Forces bad trades","Tempo advantage"],weaknesses:["Dies to evasive threats","Can't block everything","Need pressure"],skillLevel:"High"}],tips:["Understand opponent's threats - discard the most dangerous ones","Use challenges efficiently - don't waste them on irrelevant creatures","Keep tempo - play threats and defense together","Hand disruption timing is crucial - anticipate what they'll play","Don't get out-valued - you need offense, not just disruption"],crossTCGComparison:{magic:"Blue tempo (Murktide, Subtlety), Delver decks, UR Murktide",yugioh:"Dark World (hand disruption via Grapha), Tearlaments (disruption while advancing board)",pokemon:"Dialga VSTAR (disruption + control)",comparison:"Uses disruption and evasive creatures to dictate game pace while preventing opponent's key plays"}},control:{name:"Control / Lockdown",emoji:"🛡️",description:"Answer everything opponent plays. Win condition: Survive until endgame, then deploy unbeatable threats.",coreMechanic:"Heavy removal and disruption, then win with high-impact cards",lorcanaExamples:[{archetype:"Emerald/Sapphire with Control shells",keyCards:["Prince Phillip - Vanquisher of Foes","Malicious, Mean and Scary","You're Welcome","Mother Knows Best","Basil"],gameplan:"Answer threats with targeted removal. Board wipes for big threats. Clarabelle generates card advantage. Win with steady lore generation.",strengths:["Answers everything","Late game power","Flexible"],weaknesses:["Dies to early aggro","Hand disruption","Haymaker threats"],skillLevel:"High"}],tips:["Know the meta - pack answers for the top decks","Keep enough mana/ink open to answer threats","Prioritize removal - every threat dealt is a turn gained","Don't board wipe unless necessary - maintain life total","Have a win condition - removal alone doesn't win games"],crossTCGComparison:{magic:"UW Control (Counterspell, Wrath of God), Blue-based control decks",yugioh:"Paleozoic Dinosaur (floodgate control), Skill Drain control",pokemon:"Turbo Pikachu with disruption elements",comparison:"Uses defensive cards and removal to reach late game where superior resources take over"}},cardAdvantage:{name:"Card Advantage / Value",emoji:"📚",description:"Generate more cards/value than opponent. Win condition: Outresource opponent until they run out of answers.",coreMechanic:"Play creatures that replace themselves or generate multiple cards worth of value",lorcanaExamples:[{archetype:"Clarabelle Value Decks",keyCards:["Clarabelle - Light on Her Hooves","Donald Duck - Perfect Gentleman","Develop Your Brain","Vision of the Future","Improvise"],gameplan:"Build ink. Play Clarabelle for massive card draw. Use extra cards to generate more threats/removal. Overwhelm with resources.",strengths:["Card advantage engine","Creates inevitability","Refills hand"],weaknesses:["Dies before Clarabelle","Hand disruption","Needs ink"],skillLevel:"Medium"}],tips:["Prioritize card advantage creatures - they're worth more than regular threats","Calculate advantage: each card worth how many of opponent's cards?","Don't be greedy - sometimes you need to use advantage immediately","Be aware of hand size - can't generate advantage if you're at max cards","Look for synergies that generate multiple cards of advantage"],crossTCGComparison:{magic:"Esper Control with card draw, Mulldrifter builds, Yorion turbo",yugioh:"Pot of Prosperity, Spright (generates tokens + draw), Swordsoul (value generation)",pokemon:"Draw-heavy decks (Miltank, Junk Hunt), VSTAR decks with draw power",comparison:"Centers on cards that replace themselves or generate 2-for-1 value"}},comboSynergyBased:{name:"Combo / Synergy",emoji:"🔗",description:"Build synergistic engines where cards work together. Win condition: Execute key synergy combinations for overwhelming value.",coreMechanic:"Play cards that interact with each other for multiplicative value",lorcanaExamples:[{archetype:"Enigmatic Inkcaster Combo",keyCards:["Enigmatic Inkcaster","One-cost creatures (28 copies)","Amethyst Chromicon","Show Me More!","Gathering Knowledge"],gameplan:"Play 2 creatures per turn to trigger Inkcaster free lore. Refill hand when needed. Stack synergies to create inevitability.",strengths:["Multiplying lore","Hand refill synergies","Inevitable","Very cheap"],weaknesses:["Dies to removal","Linear strategy","Dies to fast aggro"],skillLevel:"Low-Medium"},{archetype:"Tramp Street-Smart Dog synergy",keyCards:["Tramp - Street-Smart Dog","Lady/Tramp variants","Yzma - Exasperated Schemer","Bobby Zimuruski","Lilo - Escape Artist"],gameplan:"Play dogs to fuel Tramp. Use discard synergies (Yzma, Bobby) to smooth hand while gaining lore. Creatures double as fuel.",strengths:["Synergistic overlap","Smooth draws","Multiple paths to lore"],weaknesses:["Requires specific pieces","Vulnerable to disruption","Telegraph strategy"],skillLevel:"Medium-High"}],tips:["Identify synergy payoff cards - build around them","Don't force synergies - cards must be good on their own","Have multiple paths - if one synergy doesn't come together, have backup","Explode carefully - don't waste synergies on irrelevant situations","Be patient - synergy decks often operate on their own timeline"],crossTCGComparison:{magic:"Storm (multiple spells = big effect), Combo decks like Jeskai Murktide, Living End",yugioh:"Synchron synergy (Tuners + non-Tuners), Spright (small creatures = big effects), Tearlaments (mill synergies)",pokemon:"Lost Box (setup/synergy), Mirage Gate decks",comparison:"Payoff cards reward playing related cards; winning involves achieving critical mass of synergies"}}},a={magicToLorcana:{name:"Magic: The Gathering → Disney Lorcana",comparisons:[{mtgArchetype:"Green Ramp",mtgDescription:"Accelerate to big creatures (Llanowar Elves, Cultivate, Craterhoof Behemoth)",lorcanaEquivalent:"Emerald/Sapphire Ink Acceleration",lorcanaCards:["Tipo - Growing Son","Sail the Azurite Sea","Prince Phillip"],similarity:"Both accelerate resources early to deploy threats ahead of curve",differences:"Lorcana has max 3 ink per turn; MTG can ramp multiple lands each turn"},{mtgArchetype:"Red Aggro",mtgDescription:"Fast creatures + burn (Goblin Guide, Lightning Bolt, Fury)",lorcanaEquivalent:"Amber/Emerald Aggro or Amethyst/Emerald Hyper-Aggro",lorcanaCards:["Lady - Decisive Dog","Tramp - Enterprising Dog","Bobby Zimuruski"],similarity:"Both output maximum early pressure to win by turn 4-5",differences:"Lorcana has no pure burn; relies on creature damage; more synergy-focused"},{mtgArchetype:"Blue-X Control",mtgDescription:"Counterspells + removal (Force of Will, Swords to Plowshares, Wrath of God)",lorcanaEquivalent:"Emerald/Sapphire Control or multi-ink control shells",lorcanaCards:["Prince Phillip - Vanquisher of Foes","Malicious, Mean and Scary","Basil"],similarity:"Both control board while setting up superior late-game threats",differences:"Lorcana has no counterspells (reactive only); uses creature-based hand disruption (Basil) instead"},{mtgArchetype:"Blue Tempo",mtgDescription:"Cheap threats + disruption (Murktide, Subtlety, Daze)",lorcanaEquivalent:"Sapphire/Steel Tempo or disruption-heavy decks",lorcanaCards:["Basil - Undercover Detective","Royal Guard","Sapphire discard effects"],similarity:"Both use evasive creatures + disruption to dictate game pace",differences:"Lorcana disruption is more challenge-based; less counterspell-heavy"},{mtgArchetype:"Jund/GX Midrange",mtgDescription:"Efficient creatures + flexible removal (Tarmogoyf, Fatal Push, Murktide)",lorcanaEquivalent:"Amethyst/Steel or Amber/Amethyst Lantern",lorcanaCards:["Calhoun - Bold Knight","Captain Hook","Lantern","The Horseman Strikes"],similarity:"Both balance offense/defense with efficient creatures at every cost",differences:"Lorcana midrange is more color-dependent; relies more on ink curves than mana colors"},{mtgArchetype:"Esper/UW Combo",mtgDescription:"Synergistic creatures (Soulherder, Ephemerate, Mulldrifter)",lorcanaEquivalent:"Enigmatic Inkcaster combo or Tramp synergy decks",lorcanaCards:["Enigmatic Inkcaster","Amethyst Chromicon","Tramp - Street-Smart Dog"],similarity:"Both use synergistic overlaps to generate multiplicative value",differences:"Lorcana synergies are creaturefocused; MTG uses more spell-creature interplay"}]},yugiohToLorcana:{name:"Yu-Gi-Oh! → Disney Lorcana",comparisons:[{yugiohArchetype:"Blue-Eyes White Dragon (BEWD)",yugiohDescription:"Big monsters + draw (Blue-Eyes, Bewd Fusion, Pot of Prosperity)",lorcanaEquivalent:"Emerald/Sapphire Ink Acceleration Control",lorcanaCards:["Tipo","Clarabelle","Prince Phillip - Vanquisher of Foes"],similarity:"Both accelerate resources to deploy powerful late-game threats + draw cards",differences:"BEWD uses Fusion Summon for boss monsters; Lorcana uses ink + expensive cards"},{yugiohArchetype:"Dark World",yugiohDescription:"Hand disruption + discard outlets (Grapha, Dark World Tour)",lorcanaEquivalent:"Sapphire/Amethyst hand disruption decks",lorcanaCards:["Basil - Undercover Detective","Sapphire discard effects","Yzma - Exasperated Schemer"],similarity:"Both use hand disruption and forced discards as primary strategy",differences:"Dark World benefits from discard; Lorcana uses discard as output with creatures"},{yugiohArchetype:"Infernoid (Burn/Aggro)",yugiohDescription:"Fast creatures + burn (multiple Infernoids, Reasoning, Charge of the Light Brigade)",lorcanaEquivalent:"Amber/Emerald Dogs or Amethyst/Emerald Hyper-Aggro",lorcanaCards:["Lady - Decisive Dog","Tramp variants","Enigmatic Inkcaster"],similarity:"Both rush down opponent quickly with cheap creatures and burn out from 20",differences:"Lorcana uses only creature damage (no pure burn); more synergy-dependent"},{yugiohArchetype:"Swordsoul (Balanced)",yugiohDescription:"Efficient creatures + synergy (Mirrorjade, Longyuan, Protos)",lorcanaEquivalent:"Amethyst/Steel Midrange or Amber/Amethyst Lantern",lorcanaCards:["Calhoun","Captain Hook","Lantern","Mowgli"],similarity:"Both balance offense/defense with creatures that generate value",differences:"Swordsoul uses Synchro/XYZ Summon; Lorcana purely ink-based"},{yugiohArchetype:"Synchron (Combo/Synergy)",yugiohDescription:"Tuner + non-Tuner synergy (Synchron creatures, multiple Synchro plays)",lorcanaEquivalent:"Enigmatic Inkcaster combo or Tramp/Dog synergies",lorcanaCards:["Enigmatic Inkcaster","One-cost creatures","Tramp - Street-Smart Dog"],similarity:"Both hinge on synergistic relationships between card types for multiplicative value",differences:"Synchron uses summon mechanics; Lorcana purely creature/ability synergy"},{yugiohArchetype:"Tearlaments (Control with Synergy)",yugiohDescription:"Mill-based synergy + disruption (Scheiren, Rulkallos, Multiple effects)",lorcanaEquivalent:"Control-based midrange with synergy (Emerald/Sapphire control shells)",lorcanaCards:["Emerald/Sapphire with Basil for disruption","Clarabelle for advantage"],similarity:"Both use synergies that advance board state while controlling opponent",differences:"Tearlaments milling-based; Lorcana is pure removal/character play"}]},pokemonToLorcana:{name:"Pokémon TCG → Disney Lorcana",comparisons:[{pokemonArchetype:"Malamar acceleration",pokemonDescription:"Resource acceleration via abilities (Malamar Ability, Energy accelerators)",lorcanaEquivalent:"Emerald/Sapphire ink acceleration",lorcanaCards:["Tipo - Growing Son","Sail the Azurite Sea"],similarity:"Both use abilities/effects to accelerate resources beyond normal rate",differences:"Pokémon uses Energy acceleration; Lorcana uses ink generator cards"},{pokemonArchetype:"Hyperaggro (Pikachu VMAX, Regigigas)",pokemonDescription:"Fast, cheap cards that snowball (Pikachu line, Galarian Rapidash)",lorcanaEquivalent:"Amethyst/Emerald Hyper-Aggro or Amber/Emerald Dogs",lorcanaCards:["Enigmatic Inkcaster","Lady - Decisive Dog","28 one-cost creatures"],similarity:"Both use extreme early pressure with cheap synergistic creatures",differences:"Pokémon relies on damage output; Lorcana on lore generation"},{pokemonArchetype:"Turbo Pike (Disruption + Combo)",pokemonDescription:"Draw + disruption + synergy (Colress, Crobat, draw engines)",lorcanaEquivalent:"Sapphire/Steel Tempo or disruption-heavy control",lorcanaCards:["Basil - Undercover Detective","Sapphire disruption","Royal Guard"],similarity:"Both balance draw, disruption, and threats for tempo advantage",differences:"Pokémon uses Items/Supporters; Lorcana pure creature-based"},{pokemonArchetype:"VSTAR Box or Setup decks",pokemonDescription:"Ramp to VSTAR with draw/setup (Lugia VSTAR, Miltank, setup creatures)",lorcanaEquivalent:"Emerald/Sapphire control with card advantage",lorcanaCards:["Clarabelle - Light on Her Hooves","Tipo","Prince Phillip"],similarity:"Both accelerate resources and generate card advantage for late game",differences:"Pokémon uses VSTAR as powerhouses; Lorcana uses expensive efficient creatures"},{pokemonArchetype:"Lost Box synergy",pokemonDescription:"Synergistic creatures (lost zone mechanics, specific setups)",lorcanaEquivalent:"Enigmatic Inkcaster or Tramp synergy decks",lorcanaCards:["Enigmatic Inkcaster","Tramp synergies","Discard outlets"],similarity:"Both leverage synergistic mechanics between specific cards",differences:"Lost Box uses zone mechanics; Lorcana uses ability triggers"}]},universalArchetypeFramework:{description:"All TCGs share these core playstyle frameworks",archetypes:[{type:"Aggro/Fast",description:"Win quickly before opponent stabilizes",mtg:"Red Deck Wins, White Weenie",yugioh:"Infernoid, Speedroid, Red-Eyes",pokemon:"Pikachu, Miltank fast decks",lorcana:"Amber/Emerald Dogs, Amethyst/Emerald Hyper-Aggro",mechanics:"Low mana cost, high early damage, snowball effects"},{type:"Control/Defensive",description:"Survive until winning with late-game superiority",mtg:"UW Control, Four-Color Control",yugioh:"Paleozoic Dinosaur, Skill Drain control",pokemon:"Turbo Dialga or setup control decks",lorcana:"Emerald/Sapphire Control shells",mechanics:"Removal, disruption, late-game bombs, resource advantage"},{type:"Midrange",description:"Balance offense and defense, generate superior value",mtg:"Jund, Grixis Midrange",yugioh:"Swordsoul, Tearlaments",pokemon:"Lugia VSTAR, Raichu-focused builds",lorcana:"Amethyst/Steel, Amber/Amethyst Lantern",mechanics:"Efficient creatures, flexible answers, value generation"},{type:"Tempo",description:"Control game pace with cheap disruption + threats",mtg:"Blue Murktide, Delver",yugioh:"Swordsoul (some variants), Drytron",pokemon:"Dialga disruption variants",lorcana:"Sapphire/Steel Tempo, disruption-heavy builds",mechanics:"Evasive threats, disruption, tempo advantage"},{type:"Ramp/Acceleration",description:"Accelerate resources to deploy powerful late-game threats",mtg:"Green Ramp, Amulet Titan",yugioh:"Blue-Eyes, Synchron decks",pokemon:"Malamar, energy accelerators",lorcana:"Emerald/Sapphire Ink Acceleration",mechanics:"Resource acceleration, mana/ink/energy ramp, big threat payoffs"},{type:"Combo/Synergy",description:"Execute key synergies for overwhelming value",mtg:"Storm, Yawgmoth, Pod variants",yugioh:"Spright, Enigmatic Inkcaster",pokemon:"Lost Box, specific synergy decks",lorcana:"Enigmatic Inkcaster deck, Tramp synergies",mechanics:"Synergistic overlaps, multiplicative value, specific piece requirements"}]}},r={acceleration:"Speeding up resource generation (mana, ink, energy) beyond normal rate",synergy:"Cards that work together for more value than individual cards",tempo:"Controlling the game by being ahead on resource efficiency/board state",value:"Generating more resources/advantage than opponent on a per-card basis",pressure:"Forcing opponent to deal with your board state",stabilize:"Returning to a safe board state after being behind",overextend:"Playing more creatures than necessary, vulnerable to mass removal",grinding:"Winning through small advantages accumulated over many turns",haymaker:"A large threat that takes over the game single-handedly",evasion:"Creatures that can't be blocked by certain types of creatures"},t={lorcanaPlaystyles:e,crossTCGComparisons:a,playStyleGlossary:r};export{a as crossTCGComparisons,t as default,e as lorcanaPlaystyles,r as playStyleGlossary};
